+    m5_FF_GG_HH_II_epilogue_b(reg_cache, a, k);
+    m5_FF_GG_HH_II_epilogue_a(a, t);
+
+    // rtmp1 = c & (~d)
+    __ andn(rtmp1, c, d);
+
+    // rtmp2 = b & d
+    __ andr(rtmp2, b, d);
@@ -5247,2 +5277,2 @@
