+    md5_HH_b(reg_cache, a, b, c, d, k, s, t, rtmp1, rtmp2);
+    md5_HH_c(reg_cache, a, b, c, d, k, s, t, rtmp1, rtmp2);
@@ -5275,0 +5331,3 @@
+    m5_FF_GG_HH_II_epilogue_b(reg_cache, a, k);
+    m5_FF_GG_HH_II_epilogue_a(a, t);
+
@@ -5279,1 +5338,2 @@
