+    m5_FF_GG_HH_II_epilogue_c(a, rtmp1);
+    m5_FF_GG_HH_II_epilogue_d(a, b, s);
@@ -5477,0 +5537,2 @@
+    // pre-compute (c ^ d) for the first HH round.
+    __ xorr (rtmp2, c, d);
